import heapq
from typing import Mapping, Optional, Tuple, List


def shortest_path(adj: Mapping[str, Mapping[str, int]], src: str, dst: str) -> Optional[Tuple[int, List[str]]]:
    """
    Find the shortest route by road length between two depots.

    ``adj`` is an adjacency map as built by ``build_adjacency`` (directed or not) with
    non-negative km values. Returns ``(total_km, path)`` where ``path`` lists the depot
    codes from ``src`` to ``dst`` inclusive; ``src == dst`` gives ``(0, [src])``.
    Returns None when ``dst`` cannot be reached from ``src``.

    Real networks often contain several routes of equal length; the function must
    always return the same route for the same network, independent of dict insertion
    order.

    Raises KeyError if ``src`` or ``dst`` is not a key of ``adj``.

    Example:
        net = {"A": {"B": 2}, "B": {"A": 2, "C": 3}, "C": {"B": 3}}
        shortest_path(net, "A", "C") == (5, ["A", "B", "C"])
    """
    if src not in adj:
        raise KeyError(src)
    if dst not in adj:
        raise KeyError(dst)

    if src == dst:
        return (0, [src])

    # Dijkstra with deterministic tie-breaking: heap entries are
    # (distance, path_tuple, node) so equal distances break by lexicographic
    # path order, making the result independent of dict insertion order.
    start_path = (src,)
    heap: list[tuple[int, tuple, str]] = [(0, start_path, src)]
    best: dict[str, tuple[int, tuple]] = {src: (0, start_path)}

    while heap:
        dist, path, node = heapq.heappop(heap)

        # Skip if we already found a better (or equal with lex-smaller path)
        if node in best:
            bd, bp = best[node]
            if dist > bd or (dist == bd and path > bp):
                continue

        if node == dst:
            return (dist, list(path))

        for nbr, weight in sorted(adj[node].items()):
            nd = dist + weight
            npath = path + (nbr,)
            if nbr not in best or (nd, npath) < best[nbr]:
                best[nbr] = (nd, npath)
                heapq.heappush(heap, (nd, npath, nbr))

    return None
