        else:
            _set_shortest(adj, from_code, to_code, km)
            _set_shortest(adj, to_code, from_code, km)

    return adj


def _set_shortest(adj: Dict[str, Dict[str, int]], src: str, dst: str, km: int) -> None:
    """Set the distance from src to dst, keeping the minimum if already present."""
    current = adj[src].get(dst)
    if current is None or km < current:
        adj[src][dst] = km
